function applyWorksAdd(poets) {
  const idx = /* @__PURE__ */ new Map();
  for (const p of poets) idx.set(p.id, p);
  let n = 0;
  for (const a of WORKS_ADD) {
    const p = idx.get(a.poetId);
    if (!p) continue;
    const node = p.nodes.find((x) => x.id === a.nodeId);
    if (!node) continue;
    const seen = new Set(node.works.map((w) => w.id));
    for (const w of a.works) {
      if (seen.has(w.id)) continue;
      node.works.push(w);
      n++;
    }
  }
  return n;
}

